B.bjy=s([B.avk,B.avx,B.aw9,B.aw2,B.avu,B.awx,B.awh,B.auT,B.av9,B.avb],t.bo)
B.auH=new A.hy(60,B.bjy)
B.avB=new A.ai(2,"Bayi dipangku orang tua atau pengasuh. Minta anak untuk menyusun kubus. Apakah anak dapat menyusun 4 kubus?",B.aC,null)
B.awb=new A.ai(3,"Bayi dipangku orang tua atau pengasuh. Tanpa bimbingan, petunjuk, atau bantuan Anda, dapatkah anak menunjuk paling sedikit 2 bagian tubuhnya dengan benar (rambut, mata, hidung, mulut, atau bagian badan yang lain)?",B.au,null)
B.awp=new A.ai(4,'Tanyakan kepada orang tua atau pengasuh, apakah anak mampu menggabungkan 2 kata berbeda ketika berbicara, misalnya "Minum susu" atau "Main bola"? "Terima kasih" dan "Da-dah" tidak termasuk.',B.au,null)
B.auO=new A.ai(5,"Tanyakan kepada orang tua atau pengasuh, apakah anak dapat melepas pakaiannya seperti baju, rok, atau celana?",B.aI,null)
B.ava=new A.ai(6,"Tanyakan kepada orang tua atau pengasuh, apakah anak dapat makan dengan menggunakan sendok sendiri tanpa banyak yang tumpah?",B.aI,null)
B.awF=new A.ai(7,u.I,B.az,null)
B.aw7=new A.ai(8,"Tanyakan kepada orang tua atau pengasuh, apakah anak dapat berjalan naik tangga sendiri? Jawab 'Ya' jika ia naik tangga dengan posisi tegak atau berpegangan pada dinding atau pegangan tangga. Jawab 'Tidak' jika ia naik tangga dengan merangkak, orang tua tidak memperbolehkan anak naik tangga, atau anak harus berpegangan pada seseorang.",B.az,null)
B.av2=new A.ai(9,"Letakkan bola tenis di depan kaki anak. Apakah ia dapat menendang ke depan tanpa berpegangan pada apapun?",B.az,null)
B.aww=new A.ai(10,'Ikuti perintah dengan seksama. Jangan memberi isyarat dengan telunjuk atau mata pada saat memberikan perintah berikut ini: "Ambil kertas" "Ambil pensil" "Tutup pintu" Dapatkah anak melakukan perintah tersebut?',B.au,null)
B.bqE=s([B.D5,B.avB,B.awb,B.awp,B.auO,B.ava,B.awF,B.aw7,B.av2,B.aww],t.bo)
B.auI=new A.hy(24,B.bqE)
B.av1=new A.ai(1,"Bayi diposisikan terlentang. Ambil gulungan wool merah, letakkan di atas wajah di depan mata bayi. Gerakkan wool dari samping kiri ke kanan kepala. Apakah ia dapat mengikuti gerakan Anda dengan menggerakkan kepala sepenuhnya dari satu ke sisi yang lain?",B.aC,"assets/kpsp/kpsp_6_1.png")
B.awy=new A.ai(2,"Pada posisi bayi terlentang, pegang kedua tangannya lalu tarik perlahan ke posisi duduk. Dapatkah bayi mempertahankan lehernya secara kaku seperti pada gambar? Jawab 'Tidak' bila kepala bayi jatuh kembali seperti gambar.",B.az,"assets/kpsp/kpsp_6_2.png")
B.awc=new A.ai(3,"Ketika bayi tengkurap di alas yang datar, apakah ia dapat mengangkat dada dengan kedua lengannya sebagai penyangga seperti pada gambar?",B.az,"assets/kpsp/kpsp_6_3.png")
B.av0=new A.ai(4,"Bayi dipangku orang tua atau pengasuh. Dapatkah bayi mempertahankan posisi kepala dalam keadaan tegak dan stabil? Jawab 'Tidak' bila kepala bayi cenderung jatuh ke kanan, kiri, atau ke dadanya.",B.az,null)
B.awN=new A.ai(5,"Bayi dipangku orang tua atau pengasuh. Sentuhkan pensil di punggung tangan atau ujung jari bayi (jangan meletakkan di atas telapak tangan bayi). Apakah bayi dapat menggenggam pensil itu selama beberapa detik?",B.aC,"assets/kpsp/kpsp_6_5.png")
B.av4=new A.ai(6,"Bayi dipangku orang tua atau pengasuh. Dapatkah bayi mengarahkan matanya pada benda kecil sebesar kacang, kismis atau uang logam? Jawab 'Tidak' jika ia tidak dapat mengarahkan matanya.",B.aC,null)
B.awV=new A.ai(7,"Bayi dipangku orang tua atau pengasuh. Dapatkah bayi meraih mainan yang diletakkan agak jauh namun masih berada dalam jangkauan tangannya?",B.aC,null)
B.awE=new A.ai(8,"Tanyakan kepada orang tua atau pengasuh, pernahkah bayi berbalik paling sedikit 2 kali, dari terlentang ke tengkurap atau sebaliknya?",B.az,null)
B.auY=new A.ai(9,"Tanyakan kepada orang tua atau pengasuh, pernahkah bayi mengeluarkan suara gembira bernada tinggi atau memekik tetapi bukan menangis?",B.au,null)
B.avc=new A.ai(10,"Tanyakan kepada orang tua atau pengasuh, pernahkah orang tua atau pengasuh melihat bayi tersenyum ketika melihat mainan yang lucu, gambar, atau binatang peliharaan pada saat ia bermain sendiri?",B.aI,null)
