B.agX=new A.hT(1,"Hubungan dengan orang lain","Sesuai usia; tidak ada kesulitan relasi.","Abnormal ringan: kadang menghindari tatap mata, malu berlebih.","Abnormal sedang: menyendiri, perlu usaha kuat menarik perhatian.","Abnormal berat: konsisten menyendiri, hampir tak merespons.")
B.ah_=new A.hT(2,"Imitasi (meniru)","Meniru suara, kata, dan gerak sesuai keterampilannya.","Abnormal ringan: meniru hal sederhana, kadang perlu didorong.","Abnormal sedang: meniru sewaktu-waktu, butuh bantuan kuat.","Abnormal berat: jarang/tak pernah meniru meski dibantu.")
B.agY=new A.hT(3,"Respon emosi","Respon emosi sesuai situasi dan usia.","Abnormal ringan: kadang reaksi emosi agak tidak sesuai.","Abnormal sedang: reaksi jelas tidak sesuai; terhambat/berlebihan.","Abnormal berat: respon jarang sesuai; sulit diubah.")
B.ah0=new A.hT(4,"Penggunaan tubuh","Gerak santai, lincah, terkoordinasi sesuai usia.","Abnormal ringan: sedikit kaku/repetitif/koordinasi buruk.","Abnormal sedang: gerakan aneh nyata (jinjit, mengayun, dll).","Abnormal berat: gerakan aneh intens dan menetap.")
B.ah7=new A.hT(5,"Penggunaan objek","Minat dan penggunaan mainan/objek sesuai.","Abnormal ringan: minat/cara bermain agak tidak lazim.","Abnormal sedang: fokus pada bagian objek, cara bermain aneh.","Abnormal berat: keasyikan aneh intens, sulit dialihkan.")
B.ah3=new A.hT(6,"Adaptasi terhadap perubahan","Menerima perubahan rutin tanpa stres berlebih.","Abnormal ringan: melanjutkan aktivitas/material yang sama.","Abnormal sedang: aktif menolak perubahan, sulit dialihkan.","Abnormal berat: reaksi hebat/tantrum terhadap perubahan.")
B.ah5=new A.hT(7,"Respon visual","Perilaku visual normal sesuai usia.","Abnormal ringan: kadang perlu diingatkan untuk melihat objek.","Abnormal sedang: tatapan kosong/menghindar, tertarik cahaya.","Abnormal berat: konsisten menghindari tatapan, sangat aneh.")
B.ah6=new A.hT(8,"Respon pendengaran","Perilaku mendengar normal sesuai usia.","Abnormal ringan: respon suara kurang/berlebih sebagian.","Abnormal sedang: respon suara bervariasi, kadang abai/terkejut.","Abnormal berat: reaksi sangat berlebihan/tidak bereaksi.")
B.agW=new A.hT(9,"Respon rasa, bau, raba","Eksplorasi & respon sentuh/bau/rasa sesuai usia.","Abnormal ringan: memasukkan benda ke mulut, reaksi nyeri tak lazim.","Abnormal sedang: cukup asyik menyentuh/mencium/merasakan.","Abnormal berat: keasyikan berlebih; respon nyeri sangat aneh.")
B.ah2=new A.hT(10,"Ketakutan dan kecemasan","Rasa takut/cemas sesuai situasi dan usia.","Abnormal ringan: takut/cemas sedikit lebih/kurang dari normal.","Abnormal sedang: takut/cemas jelas lebih/kurang dari sewajarnya.","Abnormal berat: takut menetap pada hal tak berbahaya / tak waspada bahaya.")
B.ah8=new A.hT(11,"Komunikasi verbal","Komunikasi verbal normal sesuai usia.","Abnormal ringan: bicara terlambat; sebagian ekolalia.","Abnormal sedang: bicara campur jargon/ekolalia/kata terbalik.","Abnormal berat: tak memakai kata bermakna; suara aneh.")
B.ah4=new A.hT(12,"Komunikasi non-verbal","Komunikasi non-verbal normal sesuai usia.","Abnormal ringan: menunjuk samar untuk yang diinginkan.","Abnormal sedang: sulit ekspresikan kebutuhan non-verbal.","Abnormal berat: gerak isyarat aneh, tak paham isyarat orang.")
B.agZ=new A.hT(13,"Tingkat aktivitas","Aktivitas normal sesuai usia dan keadaan.","Abnormal ringan: agak gelisah atau agak lambat.","Abnormal sedang: sangat aktif sulit dikendalikan / sangat letargi.","Abnormal berat: aktivitas/inaktivitas ekstrem.")
B.agV=new A.hT(14,"Respon intelektual","Kecerdasan normal dan konsisten di berbagai area.","Abnormal ringan: agak terlambat di segala bidang.","Abnormal sedang: umumnya terlambat, mendekati normal di 1 area.","Abnormal berat: sangat tak merata; menonjol di 1-2 area saja.")
B.ah1=new A.hT(15,"Kesan umum","Bukan autistik: tidak ada karakteristik autisme.","Autisme ringan: sedikit gejala.","Autisme sedang: beberapa gejala.","Autisme berat: banyak gejala/derajat ekstrem.")
B.bmp=s([B.agX,B.ah_,B.agY,B.ah0,B.ah7,B.ah3,B.ah5,B.ah6,B.agW,B.ah2,B.ah8,B.ah4,B.agZ,B.agV,B.ah1],A.a5("A<hT>"))
